// Sybill on the organization's own API key: every operation in its published API (calls and their transcripts,
// deals, accounts, emails, Ask Sybill, and importing your own records). actions.json is generated by
// `bun scripts/openapi-actions.ts sybill`. Sybill's webhooks can only be set up in its dashboard, so new calls, deals,
// accounts and emails start automations by polling (polls/sybill.ts).
import type { OwnApp } from "../index";
import { type Api, call, specActions } from "../openapi";

const api: Api = {
  name: "Sybill",
  base: "https://api.sybill.ai",
  tokenHelp: "app.sybill.ai/settings/integrations/api-keys",
};

export const sybill: OwnApp = {
  app: "sybill",
  name: "Sybill",
  logo: "/logos/sybill.svg",
  keyField: {
    label: "API key",
    help: "In Sybill: Settings → Integrations → API Keys (app.sybill.ai/settings/integrations/api-keys) → Create, then copy the key (it's shown only once). Tick Export to read calls, deals and accounts, Ask Sybill to ask questions about them, and Import to add your own calls, emails and documents. The key is for the whole organization and sees only calls shared with it, not anyone's private ones. API keys come with Sybill plans that include API access.",
    placeholder: "sk_live_...",
  },
  async check(key) {
    const me = (await call(api, key, { method: "GET", path: "/v1/health", query: [], headers: [] }, {})) as { org_id?: string; scopes?: string[] };
    return me.scopes?.length ? `Sybill (${me.scopes.join(", ")})` : undefined;
  },
  actions: await specActions(new URL("./actions.json", import.meta.url), api),
};
